const tasks = yield* Database.query(Filter.type(types['com.example.type.task'], { status: 'open' })).run;
const results = [];
for (const task of tasks) {
  const score = yield* Operation.invoke(ops['dxn:com.example.operation.score'], { title: task.title });
  const value = typeof score === 'number' ? score : score.score;
  Obj.update(task, (t) => { t.priority = value; });
  results.push({ title: task.title, score: value });
}
yield* Database.flush();
yield* print('scored', results);
